CREATE SCHEMA IF NOT EXISTS privacy_ops;
CREATE TABLE privacy_ops.data_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),domain varchar(64) NOT NULL,name varchar(120) NOT NULL,classification text NOT NULL CHECK(classification IN('public','internal','personal','sensitive','restricted')),fields jsonb NOT NULL CHECK(jsonb_typeof(fields)='array'),owner varchar(120) NOT NULL,retention_rule varchar(64) NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,domain,name));
CREATE TABLE privacy_ops.processing_activities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),purpose text NOT NULL,lawful_basis text NOT NULL CHECK(lawful_basis IN('consent','contract','legal_obligation','vital_interest','public_interest','legitimate_interest')),data_categories jsonb NOT NULL,subject_categories jsonb NOT NULL,recipients jsonb NOT NULL DEFAULT '[]',consent_required boolean NOT NULL DEFAULT false,owner varchar(120) NOT NULL,policy_version varchar(30) NOT NULL,active boolean NOT NULL DEFAULT true,reviewed_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(consent_required=(lawful_basis='consent')));
CREATE TABLE privacy_ops.retention_rules(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),rule_key varchar(64) NOT NULL,domain varchar(64) NOT NULL,retention_days integer NOT NULL CHECK(retention_days BETWEEN 1 AND 3650),action text NOT NULL CHECK(action IN('delete','anonymize','archive')),legal_basis text NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,rule_key));
CREATE TABLE privacy_ops.legal_holds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),reason text NOT NULL,scope jsonb NOT NULL,starts_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,requested_by uuid NOT NULL,approved_by uuid NOT NULL,status text NOT NULL DEFAULT 'active' CHECK(status IN('active','released','expired')),released_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(requested_by<>approved_by),CHECK(expires_at>starts_at));
CREATE TABLE privacy_ops.data_subject_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),subject_id varchar(120) NOT NULL,request_type text NOT NULL CHECK(request_type IN('access','export','correct','delete','restrict','object')),status text NOT NULL CHECK(status IN('queued','verifying','processing','blocked','ready','completed','rejected','cancelled')),verified boolean NOT NULL DEFAULT false,reason text,submitted_at timestamptz NOT NULL,due_at timestamptz NOT NULL,completed_at timestamptz,artifact_key text,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(due_at>=submitted_at));
CREATE INDEX privacy_requests_queue_idx ON privacy_ops.data_subject_requests(tenant_id,status,due_at) WHERE status IN('queued','verifying','processing','blocked');
CREATE TABLE privacy_ops.request_tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),request_id uuid NOT NULL REFERENCES privacy_ops.data_subject_requests(id) ON DELETE CASCADE,domain varchar(64) NOT NULL,action text NOT NULL CHECK(action IN('export','correct','delete','anonymize','hold','restrict')),status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','running','completed','blocked','failed')),proof_hash varchar(64),error_code varchar(120),started_at timestamptz,completed_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(request_id,domain,action));
CREATE TABLE privacy_ops.processors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),name varchar(120) NOT NULL,country char(2) NOT NULL,purpose text NOT NULL,status text NOT NULL CHECK(status IN('pending','approved','suspended','terminated')),dpa_signed boolean NOT NULL DEFAULT false,subprocessors_declared boolean NOT NULL DEFAULT false,transfer_assessment boolean NOT NULL DEFAULT false,sensitive_data boolean NOT NULL DEFAULT false,risk_rank smallint NOT NULL DEFAULT 0 CHECK(risk_rank BETWEEN 0 AND 100),reviewed_at timestamptz,next_review_at timestamptz,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,name));
CREATE TABLE privacy_ops.breach_register(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),detected_at timestamptz NOT NULL,assessed_at timestamptz,severity text NOT NULL CHECK(severity IN('low','medium','high','critical')),subjects_affected integer NOT NULL DEFAULT 0 CHECK(subjects_affected>=0),personal_data boolean NOT NULL,contained boolean NOT NULL DEFAULT false,notification_required boolean NOT NULL DEFAULT false,notification_deadline timestamptz,notified_at timestamptz,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','contained','notified','closed')),owner uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX privacy_breach_deadline_idx ON privacy_ops.breach_register(tenant_id,status,notification_deadline) WHERE notification_required AND notified_at IS NULL;
CREATE TABLE privacy_ops.compliance_evidence(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),control_key varchar(120) NOT NULL,evidence_type varchar(80) NOT NULL,artifact_hash varchar(64) NOT NULL CHECK(artifact_hash~'^[a-f0-9]{64}$'),recorded_by uuid NOT NULL,recorded_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE privacy_ops.daily_metrics(tenant_id uuid NOT NULL REFERENCES platform.tenants(id),metric_date date NOT NULL,assets_total integer NOT NULL DEFAULT 0,personal_assets integer NOT NULL DEFAULT 0,sensitive_assets integer NOT NULL DEFAULT 0,retention_coverage_bps integer NOT NULL DEFAULT 0 CHECK(retention_coverage_bps BETWEEN 0 AND 10000),open_requests integer NOT NULL DEFAULT 0,overdue_requests integer NOT NULL DEFAULT 0,approved_processors integer NOT NULL DEFAULT 0,open_breaches integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(tenant_id,metric_date));
CREATE OR REPLACE FUNCTION privacy_ops.prevent_evidence_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'privacy evidence is append-only';END$$;
CREATE TRIGGER privacy_evidence_append_only BEFORE UPDATE OR DELETE ON privacy_ops.compliance_evidence FOR EACH ROW EXECUTE FUNCTION privacy_ops.prevent_evidence_mutation();
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['data_assets','processing_activities','retention_rules','legal_holds','data_subject_requests','request_tasks','processors','breach_register','compliance_evidence','daily_metrics'] LOOP EXECUTE format('ALTER TABLE privacy_ops.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE privacy_ops.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation_privacy_%I ON privacy_ops.%I USING(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)',t,t);END LOOP;END$$;
